const CACHE='yoyu-ledger-github-v3-install-2';const ASSETS=['./','./index.html','./style.css','./app.mjs?v=3-install-1','./install.mjs','./domain.mjs','./ai.mjs','./models.mjs','./schema.mjs','./advanced-core.mjs','./advanced-ui.mjs','./backup.mjs','./key-vault.mjs','./settlement-schema.mjs','./settlement-core.mjs','./settlement-ui.mjs','./invoice-scan.mjs','./invoice-ai.mjs','./vendor/jsqr.mjs','./invoice-ui.mjs','./invoice-core.mjs','./invoice-schema.mjs','./cloud.mjs','./cloud-config.mjs','./sync-core.mjs','./cloud-config.json','./vendor/supabase.mjs','./icon.svg','./icon-192.png','./icon-512.png','./manifest.webmanifest'];self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>self.skipWaiting()))});self.addEventListener('activate',e=>e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('yoyu-ledger-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));self.addEventListener('fetch',e=>{const u=new URL(e.request.url);if(e.request.method!=='GET'||u.origin!==self.location.origin||(!e.request.mode.includes('navigate')&&!ASSETS.some(p=>new URL(p,self.registration.scope).pathname===u.pathname)))return;e.respondWith(fetch(e.request).then(r=>{if(r.ok&&!r.redirected){const copy=r.clone();caches.open(CACHE).then(c=>c.put(e.request,copy))}return r}).catch(()=>caches.match(e.request).then(r=>r||(e.request.mode==='navigate'?caches.match('./index.html'):Response.error()))))});

self.addEventListener('notificationclick',event=>{event.notification.close();event.waitUntil(clients.openWindow(self.registration.scope))});
